INSERT INTO `cat_trikotaj` (`id`, `id2`, `name`, `discr`, `aktiv`, `discr2`, `title`, `keywords`, `description`, `chpu`, `data`, `cat0`) VALUES
(1, 0, 'Льняная одежда', '<p>В нашем интернет-магазине Вы можете выбрать и купить оптом, напрямую от Ивановского производителя домашнюю и повседневную одежду из льна, такую как:&nbsp;<a href=\"../../katalog/yubki-len\">Юбки</a>&nbsp; /&nbsp;<a href=\"../../katalog/topue-len\">Топы</a>&nbsp; &nbsp;/&nbsp; &nbsp;<a href=\"../../katalog/vetrovki\">Ветровки</a>&nbsp; &nbsp; /&nbsp; &nbsp;&nbsp;<a href=\"../../katalog/platya-len\">Платья</a>&nbsp; &nbsp;/&nbsp; &nbsp;<a href=\"../../katalog/zhaketi-len\">Жакеты</a>&nbsp; &nbsp;/&nbsp; &nbsp;<a href=\"../../katalog/bryuki-len\">Брюки</a>&nbsp; &nbsp;/&nbsp; &nbsp;<a href=\"../../katalog/bluzue-len\">Блузы / туники</a></p>', 1, '<p>Льняная ткань имеет очень долгую историю, которая насчитывает около пяти тысяч лет.&nbsp;</p>\r\n<p>В древности льняная ткань являлась показателем роскоши. Издревле мастера добивались высочайшего качества льняных изделий. Полотно получалось тонким, но крепким и носким, с характерным приглушённым блеском.</p>\r\n<p>Как в древности, так и в настоящее время, льняные одежды считают символом чистоты</p>\r\n<p>Впоследствии ручное ткачество отошло в прошлое, и появились ткацкие мануфактуры. В Европе дорогостоящее льняное бельё относят к классу &laquo;люкс&raquo;, а вот в России лён доступнее и дешевле.</p>\r\n<p>Льняная пряжа состоит из довольно прочных, совершенно круглых лубяных волокон.</p>\r\n<p>В зависимости от сорта льна, технологии культивации (в большей степени) и качества его последующей обработки на производстве (в меньшей степени) льняная пряжа подразделяется на пряжу из длинного волокна и короткого волокна (очес). Длинноволокнистый лён используется для изготовления изделий&nbsp; высокой износостойкости, экологичности и натуральности. Такой лён лучше подходит для изготовления тканей для повседневной одежды.</p>\r\n<p>Такие ткани обладают рядом качеств: 1 мягкость 2 шелковистость 3 воздухопроницаемость. Одежда из льна всегда считается лучшим вариантом для жаркой солнечной погоды.</p>\r\n<p>Коротковолокнистый лён обладает&nbsp; более низкой износостойкостью, ткани из него в основном имеют техническое назначение и используется во всех остальных случаях.</p>\r\n<p>&nbsp;</p>', 'Купить льняную одежду от производителя оптом и в розницу в Иваново', 'Льняная одежда,продажа, интернет магазин, иваново', 'Льняная одежда от производителя оптом и в розницу - интернет магазин Текстильный эталон. Удобная и красивая домашняя одежда. ', 'lnyanaya-odejda', '2021-10-15 06:10:33', 0);

