INSERT INTO `content_trikotaj` (`id`, `razd`, `date`, `name`, `discr`, `aktiv`, `id2`, `chpu`) VALUES
(1, 2, '2020-09-22 12:39:13', 'Как купить?', '<div style=\"max-width: 1220px; width: 100%; margin-left: auto; margin-right: auto; text-align: left;\">\r\n<p>1. Выберите необходимый товар.<br />2. Укажите необходимое количество выбранного товара.<br />3. Нажмите кнопку&nbsp;\"Положить в корзину\".<br />4. После этого вернитесь в раздел для выбора другого товара.<br />5. Для просмотра заказанного товара в корзине необходимо нажать на кнопку&nbsp;\"Товары в корзине\".<br />6. Розничные заказы отправляем 1-н раз в неделю, после 100% предоплаты.<br />7. Сумма заказа будет пересчитана согласно нашим скидкам.<br />8. Заполните все контактные данные и нажмите кнопку&nbsp;\"Оформить заказ\".<br />9. Поздравляем, ваш заказ отправлен, с вами свяжутся наши менеджеры.</p>\r\n</div>', 1, '', 'kak-kupitmz'),
(2, 2, '2020-09-22 12:39:58', 'Документы', '<table style=\"width: 400px;\" border=\"0\" align=\"center\">\r\n<tbody>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>', 1, '', 'dokumenti'),
(3, 2, '2020-09-22 12:40:41', 'Таблица размеров', '<div style=\"overflow: scroll; width: 100%;\">\r\n<table style=\"width: 100%;\" border=\"1\" cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td colspan=\"9\" valign=\"TOP\" width=\"970\">\r\n<p align=\"CENTER\">МУЖЧИНЫ</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td rowspan=\"2\" width=\"94\">\r\n<p>размеры</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">44</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">46</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">48</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">50</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">52</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">54</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">56</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">58</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"96\">\r\n<p align=\"CENTER\">S</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">M</p>\r\n</td>\r\n<td colspan=\"2\" width=\"205\">\r\n<p align=\"CENTER\">L</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">XL</p>\r\n</td>\r\n<td width=\"4355\">\r\n<p align=\"CENTER\">XXL</p>\r\n</td>\r\n<td colspan=\"3\" width=\"314\">\r\n<p align=\"CENTER\">XXXL</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>1. Обхват груди</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">88 - 91</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">92 - 95</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">96 - 99</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">100 - 103</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">104 - 107</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">108 - 111</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">112 - 115</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">116 - 119</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>2. Обхват талии</p>\r\n</td>\r