05</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">106 - 109</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">110 - 113</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">114 - 117</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>2. Обхват талии</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">61 - 65</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">64 - 68</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">67 - 71</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">70 - 74</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">73 - 77</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">76 - 80</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">79 - 83</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">82 - 86</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>3. Обхват бедер</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">89 - 93</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">92 - 96</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">95 - 99</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">98 - 102</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">101 - 105</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">104 - 108</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">107 - 111</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">110 - 114</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>4. Боковая длина</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">102 - 105</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">103 - 106</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">104 - 107</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">105 - 108</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">106 - 109</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">107 - 110</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">108 - 111</p>\r\n</td>\r\n<td width=\"95\">\r\n<p align=\"CENTER\">109 - 112</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"TOP\">\r\n<td width=\"94\">\r\n<p>5. Рост</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">164 - 171</p>\r\n</td>\r\n<td width=\"96\">\r\n<p align=\"CENTER\">172 - 179</p>\r\n</td>\r\n<td colspan=\"3\" width=\"314\">\r\n<p align=\"CENTER\">178 - 185</p>\r\n</td>\r\n<td colspan=\"3\" width=\"314\">\r\n<p align=\"CENTER\">184 - 191</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<p><strong><a class=\"lightview\" title=\"111\" href=\"../../images/c9c99699f34307a45f4e06a2dd392b2a.png\" rel=\"lightbox\"><img style=\"float: left; margin: 3px;\" src=\"../../images/.thumbs/c9c99699f34307a45f4e06a2dd392b2a_0_270_0.jpg\" alt=\"111\" width=\"264\" height=\"270\" /></a> Как снимать мерки?</strong></p>\r\n<ul>\r\n<li>Обхват груди: измеряется горизонтально по наиболее выступающим точкам груди</li>\r\n<li>Обхват талии: измеряется по естественной линии талии в самом узком месте</li>\r\n<li>Обхват бедер: измеряется горизонтально по наиболее выступающим точкам бедер</li>\r\n<li>Боковая длина: измеряется вертикально с внешней стороны от талии до пола</li>\r\n<li>Рост: измеряется без обуви, вертикально от макушки до подошвы</li>\r\n</ul>\r\n<p>Все мерки снимаются без верхней одежды, так, чтобы сантиметровая лента плотно прилегала к телу, но не была натянута</p>', 1, '', 'tablitca-razmerov'),
(4, 3, '2020-09-22 12:50:40', 'Доставка', '<div style=\"max-width: 1220px; width: 100%; margin-left: auto; margin-right: auto; text-align: left;\">\r\n<p><strong>Товар можно забрать самостоятельно со склада предприятия.</strong></p>\r\n<p>Для клиентов из регионов доставка осуществляется за счет клиента транспортными компаниями, представленными в нашем регионе, такими, как</p>\r\n<ul>\r\n<li>ЖелДор Экспедиция</li>\r\n<li>Деловые линии</li>\r\n<li>ПЭК</li>\r\n<li>Автотрейдинг</li>\r\n</ul>\r\n<p>Возможность доставки другими компаниями необходимо уточнять.</p>\r\n<p>Стоимость доставки уточняйте на сайтах транспортных компаний.</p>\r\n<p><span style=\"text-decoration: underline;\">Доставка до терминалов транспортых компаний Бесплатная.</span></p>\r\nВместе с грузом мы отправляем Вам оригиналы документов: Счет на оплату, товарную накладную по форме Торг -12, Ваш экземпляр, подписанного нами, договора и наш экземпляр для подписания Вами, который просим выслать нам по почте, также просим выслать заверенные копии Ваших учредительных документов.</div>', 1, '', 'dostavka');

