INSERT INTO `kat_trikotaj` (`id`, `name`, `discr`, `data`, `title`, `keywords`, `description`) VALUES
(1, 'Главная страница', '<h1>Льняная одежда оптом от производителя в Иваново</h1>\r\n<p>Компания ТексЭт - Текстильный Эталон ведёт свою историю с 2000 года.</p>\r\n<p>ТексЭт - производитель льняной одежды и одежды для дома.</p>\r\n<p>Производство расположено в русском Манчестере, текстильной столице нашей Родины - городе Иваново.</p>\r\n<p>Наша компания реализует свою продукцию по всей России крупным и мелким оптом, малыми и большими партиями, отгружая со склада и по предзаказу.</p>\r\n<p>Сотрудничаем с организаторами совместных покупок. Нацелены на взаимовыгодное сотрудничество, обеспечиваем гибкий подход к клиентам. Всем покупателям предоставляем скидки в зависимости от объёма покупок, действуют накопительные скидки для постоянных покупателей.</p>\r\n<p><a class=\"lightview\" style=\"color: #1b57c0; text-decoration-line: underline;\" title=\"r1\" href=\"../../images/ef9a6a753644609df39de9cdfab62d82.png\" rel=\"lightbox\"><img style=\"margin: 3px; float: left;\" src=\"../../images/.thumbs/ef9a6a753644609df39de9cdfab62d82_0_270_0.jpg\" alt=\"лен\" width=\"200\" height=\"200\" /></a></p>\r\n<p>За годы работы ассортимент постоянно расширяется. Сейчас наши клиенты могут купить напрямую от Ивановского производителя оптом и в розницу льняные изделия, такие как: блузы, льняные жакеты, льняные пиджаки, льняные платья, льняные брюки и юбки, сарафаны из льна.</p>\r\n<p>Лён идеально подходит для жарких, солнечных дней, так как не дает телу перегреваться и позволяет \"дышать\". Конечно же многим придёт на ум ассоциация о льне, как о сильно мнущемся, колючем материале, но технологии не стоят на месте и современные методы обработки позволяют добиться мягкости и шелковистости от материала. Разнообразие расцветок и принтов удовлетворят самый взыскательный спрос.</p>\r\n<p><a class=\"lightview\" title=\"r2\" href=\"../../images/9648eb371ab9135bba460d0d631fb475.png\" rel=\"lightbox\"><img style=\"margin: 3px; float: right;\" src=\"../../images/.thumbs/9648eb371ab9135bba460d0d631fb475_270_0_0.jpg\" alt=\"r2\" width=\"200\" height=\"133\" /></a> Выпускаем домашнюю одежду из трикотажа, бязи, ситца и фланели, домашние, женские халаты, спортивные костюмы, ночные сорочки, пижамы, шорты, бриджи, брюки, туники, майки, футболки.</p>\r\n<p>В большей своей массе трикотажные полотна, бязевые и фланелевые ткани выработаны из хлопка, что придает материалу мягкость, легкость, отличную воздухопроницаемость. Такие материалы приятны на ощупь и комфортны при носке.</p>\r\n<p>Текстильный рынок сильно насыщен товарами, как отечественного, так и зарубежного производства. В условиях сильной конкуренции мы уделяем максимум внимания качеству, так что бы все изделия соответствовали своему размеру, хорошо сидели по фигуре, соответствовали современным требованиям качества.</p>\r\n<p>Приглашаем стать нашим клиентом и убедиться в правильности своего выбора.</p>\r\n<p style=\"text-align: left;\">Процветания Вашему бизнесу, уюта и тепла в доме.</p>\r\n<p style=\"text-align: left;\"><span style=\"text-decoration: underline;\">ООО ТексЭт.</span></p>', '2022-02-07 07:02:56', 'Льняная одежда оптом от производителя и Ивановский трикотаж по низким ценам от производство в Иваново', 'иваново,трикотаж,ивановский, от производителя, оптом и в розницу, женский трикотаж', 'Купить женскую льняную одежду от производителя, трикотаж в Иваново оптом и в розницу - фабрика трикотажа Текстильный Эталон Россия'),
(2, 'Информация', '', '2021-06-04 06:06:05', 'Информация о работе нашей компании', 'Информация', 'Важная информация - описание как купить, документы, таблица размеров'),
(3, 'Условия работы', '<div style=\"max-width: 1220px; width: 100%; margin-left: auto; margin-right: auto; text-align: left;\">\r\n<p>Мы работаем с юридическими лицами, индивидуальными предпринимателями и физическими лицами.</p>\r\n<p>Заключаем договора поставки.</p>\r\n<p>Документы необходимые для заключения договора оптовой поставки:</p>\r\n<p><strong>Если Вы &ndash; Юридическое лицо:</strong></p>\r\n<ul>\r\n<li>Свидетельство о постановке на налоговый учет юридического лица (ИНН);</li>\r\n<li>Свидетельство о государственной регистрации юр. лица (ОГРН);</li>\r\n<li>Карточка предприятия.</li>\r\n</ul>\r\n<p><strong>Если Вы &ndash; Индивидуальный предприниматель:</strong></p>\r\n<ul>\r\n<li>Свидетельство о постановке на налоговый учет индивидуального предпринимателя (ИНН);</li>\r\n<li>Свидетельство о государственной регистрации ИП (ОГРНИП);</li>\r\n<li>Сведения о расчетном счете (если есть);</li>\r\n<li>Страница паспорта кем и когда выдан;</li>\r\n<li>Страница паспорта с фотографией;</li>\r\n<li>Страница паспорта с последним местом регистрации.</li>\r\n</ul>\r\n<p><strong>Если Вы физическое лицо:</strong></p>\r\n<ul>\r\n<li>Паспортные данные (как в разделе для ИП)</li>\r\n</ul>\r\n<p>*Все копии документов должны быть заверены надписью: &laquo;Копия верна&raquo;, проставлено число, подпись и печать (если есть).</p>\r\n<p><strong>Минимальная сумма заказа 4000 руб.</strong></p>\r\n</div>', '2021-10-28 05:10:58', 'Условия работы', 'Условия работы', 'Условия работы'),
(4, 'Как сделать заказ', '<div style=\"max-width: 1220px; width: 100%; margin-left: auto; margin-right: auto; text-align: left;\">\r\n<p>1. Выберите необходимый товар.<br />2. Укажите необходимое количество выбранного товара.<br />3. Укажите цвет изделия из предложенных в поле&nbsp;Комментарий.<br />4. Нажмите кнопку&nbsp;\"Положить в корзину\".<br />5. После этого вернитесь в раздел для выбора другого товара.<br />6. Для просмотра заказанного товара в корзине необходимо нажать на кнопку&nbsp;\"Товары в корзине\".<br />7. При достижении суммы заказа&nbsp;<strong>5</strong><strong>000 рублей</strong>&nbsp;появится кнопка&nbsp;\"Перейти к оформлению заказа\".<br />8. Сумма заказа будет пересчитана согласно нашим ценам.<br />9. Заполните все контактные данные и нажмите кнопку&nbsp;\"Оформить заказ\".<br />10. Поздравляем, ваш заказ отправлен, с вами свяжутся наши менеджеры.</p>\r\n</div>', '2020-09-22 00:09:37', 'Как сделать заказ', 'Как сделать заказ', 'Как сделать заказ'),
(5, 'Для СП', '', '2020-09-22 00:09:27', '', '', ''),
(6, 'Контакты', '<div class=\"dr1\">\r\n<h3>Наши <span class=\"rose\">контакты (производство)</span></h3>\r\n<div class=\"ph\">8 (804) 700-50-77</div>\r\n<div class=\"ml\">info@texet.biz</div>\r\n<div class=\"mp\">Ивановская обл., Ново-Талицы <br />ул. Автодоровская стр. 5</div>\r\n<h3>Режим <span class=\"rose\">работы:</span></h3>\r\nПн - Пт 09:00 до 18:00<br />Сб - Вс выходной<br />\r\n<h3>Наши <span class=\"rose\">контакты (бухгалтерия)</span></h3>\r\n<div class=\"ph\">8 (4932) 92-39-59 доб. 202</div>\r\n<div class=\"ml\">buh@ogm-group.biz</div>\r\n</div>', '2024-05-16 01:05:57', 'Контакты', 'Контакты', 'Контакты'),
(7, 'Пользовательское соглашение', '<div style=\"max-width: 1220px; width: 100%; margin-left: auto; margin-right: auto; text-align: left;\">\r\n<p><span>Соглашение о пользовании услугами интернет-магазина \"ТексЭт\".</span></p>\r\n<p>Настоящее соглашение, далее &laquo;Соглашение&raquo;, заключается между Интернет-магазином \"ТексЭт\", имеющим адрес в сети Интернет http://texet.biz, далее &laquo;Интернет-магазин&raquo; или &laquo;Сайт&raquo;, и пользователем услуг Интернет-магазина, далее &laquo;Покупатель&raquo;, и определяет условия приобретения товаров через Сайт.</p>\r\n<p>1. Основные положения</p>\r\n<p>1.1. Настоящее Соглашение заключается между Покупателем и Интернет-магазином в момент оформления заказа.<br />&nbsp;Совершая покупки на сайте Покупатель подтверждает свое согласие с условиями, установленными настоящим Соглашением.<br />&nbsp;1.2. К отношениям между Покупателем и Интернет-магазином применяются положения ГК РФ о розничной купле-продаже (&sect; 2 глава 30), а также Закон РФ &laquo;О защите прав потребителей&raquo; от 07.02.1992 № 2300-1 и иные правовые акты, принятые в соответствии с ними.<br />&nbsp;1.3. Покупателем может быть любое физическое или юридическое лицо, способное принять и оплатить заказанный им товар в порядке и на условиях, установленныx настоящим Соглашением, на территории Российской Федерации.<br />&nbsp;1.4. Покупатель несет ответственность за правильность заполнения всех пунктов формы заказа. В случае наличия ошибок или предоставления неполных сведений в полях &ldquo;ФИО&rdquo; и &ldquo;Адрес доставки&rdquo;, с Интернет-магазина полностью снимается ответственность за выполнение заказа.<br />&nbsp;1.5. Администрация Сайта имеет право отказать Покупателю в оказании Услуг в любой момент до получения оплаты без объяснения причин.<br />&nbsp;1.6. Интернет-магазин имеет право отказать Покупателю в оказании Услуг после получения оплаты в случае:<br />&nbsp;&nbsp; - 1.6.1. если товар отсутствует на складе Продавца в течение 15 рабочих дней со дня получения оплаты Интернет-магазином;<br />&nbsp;&nbsp; - 1.6.2. если у Интернет-магазина есть сомнения в достоверности сведений, предоставленных Покупателем при заполнении формы заказа, включая, но не ограничиваясь именем покупателя и адресом доставки товара.<br />&nbsp;1.7. В случае отказа в оказании услуг Интернет-магазина по одной из причин, перечисленных в п. 1.6. данного Соглашения, Интернет-магазин возвращает средства, поступившие от Покупателя, за вычетом комиссии Посредников, используемых для денежных переводов.<br />&nbsp;1.8. Возврат средств Покупателю осуществляется тем же методом и на те же платежные реквизиты, какие были использованы для оплаты услуг Интернет-магазина.<br />&nbsp;1.9. Интернет-магазин оставляет за собой право вносить изменения в настоящее Соглашение.<br />&nbsp;1.10. Настоящее Соглашение должно рассматриваться в том виде, как оно опубликовано на Сайте, и должно применяться и толковаться в соответствии с законодательством Российской Федерации.<br />&nbsp;1.11. Услуги считаются полностью оказанными Интернет-магазином с момента передачи товаров Покупателю транспортной компанией.</p>\r\n<p>2. Информация о товаре</p>\r\n<p>2.1. Товар представлен на Сайте через фото-образцы, являющиеся собственностью Интернет-магазина.<br />&nbsp;2.2. Каждый фото-образец сопровождается текстовой информацией: ценой и описанием товара.<br />&nbsp;2.3. По просьбе Покупателя менеджер Интернет-магазина обязан предоставить (по телефону или посредством электронной почты) прочую информацию, необходимую и достаточную, с точки зрения Покупателя, для принятия им решения о покупке товара.<br />&nbsp;2.4. Указанная на Сайте цена товара может быть изменена Интернет-магазином в одностороннем порядке.<br />&nbsp;2.5. В случае изменения цены товара, заказанного Покупателем, менеджер Интернет-магазина при первой возможности информирует об этом Покупателя (по телефону или посредством электронной почты) для получения подтверждения либо аннулирования заказа. При невозможности связаться с Покупателем данный заказ считается аннулированным.<br />&nbsp;2.6. Интернет-магазин оставляет за собой право расширять и сокращать товарное предложение на Сайте, регулировать доступ к покупке любых товаров, а также приостанавливать или прекращать продажу любых товаров по своему собственному усмотрению.</p>\r\n<p>3. Порядок приобретения товара</p>\r\n<p>3.1. Покупатель вправе оформить заказ на любой товар, представленный на Сайте.<br />&nbsp;Заказ может быть оформлен Покупателем следующими способами: по телефону, по электронной почте, или оформлен самостоятельно на Сайте.<br />&nbsp;3.2. После оформления заказа на e-mail Покупателя отправляется счет, подтверждающий принятие заказа, с указанием наименований выбранных товаров и общей суммы заказа, являющийся неотъемлемой частью настоящего Соглашения. Далее менеджер Интернет-магазина связывается с Покупателем (по телефону или посредством электронной почты) для получения подтверждения заказа.<br />&nbsp;3.3. При отсутствии товара на складе менеджер Интернет-магазина обязан поставить в известность об этом Покупателя (по телефону или посредством электронной почты).<br />&nbsp;3.4. При отсутствии товара Покупатель вправе заменить его другим товаром либо аннулировать заказ.</p>\r\n<p>4. Доставка и приемка-передача товара</p>\r\n<p>4.1. Доставка товара, заказанного в Интернет-магазине, в согласованном количестве и ассортименте, осуществляется Транспортной компанией либо почтой России.<br />&nbsp;4.2. Покупатель может забрать свой товар в магазине самостоятельно (самовывоз).<br />&nbsp;4.3. Отправка и доставка заказанного товара производится в оговоренные с Покупателем сроки.</p>\r\n<p>5. Оплата товара</p>\r\n<p>5.1. Оплата товара производится за наличный расчёт при 100% предоплате&nbsp; по безналичному расчету банковской картой или через кассира операциониста.<br />&nbsp;5.2. Товар оплачивается в рублях РФ.</p>\r\n<p>6. Возврат товара</p>\r\n<p>6.1. Интернет-магазин не осуществляет возврат товара или обмен его на деньги, в случае, если приобретенный товар был уже (постиран или нарушена целостность товара).</p>\r\n<p>7. Ответственность</p>\r\n<p>7.1. Интернет-магазин не несет ответственности за любые расходы Покупателя или прямой либо косвенный ущерб, который может быть нанесен Покупателю вследствие использования услуг Интернет-магазина, причиненный Пользователю в результате использования или невозможности пользования Услугами и понесенный в результате ошибок, пропусков, перерывов в работе, удаления файлов, изменения функций, дефектов упаковки, задержек в работе при передаче данных и т.п., случившихся не по вине Интернет-магазина.<br />&nbsp;7.2. Интернет-магазин не несет ответственности за действия смежных служб и сервисов, используемых для предоставления Услуг Покупателю, но не принадлежащих Интернет-магазину, как то: банки, транспортные компании, интернет-провайдеры, емейл-сервисы, платежные системы и т.д.</p>\r\n<p>8. Обязанности Покупателя</p>\r\n<p>8.1. Покупатель обязуется самостоятельно знакомиться с текстом данного Соглашения, проверять наличие изменений Соглашения и его приложений. 8.2. Покупатель обязуется своевременно обеспечивать Интернет-магазин всей необходимой информацией для выполнения требуемого обслуживания и отправки заказа. При недостатке необходимой информации Интернет-магазин оставляет за собой право не предоставлять обслуживание Покупателю.<br />&nbsp;8.3. Покупатель обязуется своевременно оплачивать счета. Интернет-магазин не производит обслуживание Покупателя в случае, если предоставленных Покупателем средств недостаточно для оказания Услуг.</p>\r\n<p><br />9. Обязанности Интернет-магазина</p>\r\n<p>9.1. Интернет-магазин обязуется предоставить Покупателю Услуги и выполнять касающиеся Услуг требования Покупателей, если запрос Покупателя не противоречит правилам и ограничениям на обслуживание, изложенным в данном Соглашении.<br />&nbsp;9.2. Сохранять конфиденциальность данных о Покупателе. Данные о Покупателе могут быть предоставлены только в случаях, предусмотренных законодательством Российской Федерации.<br />&nbsp;9.3. Предоставлять Покупателю возможность получения информации статусе его заказа.</p>\r\n<p>10. Срок действия Соглашения, изменение условий и прекращение предоставления услуг</p>\r\n<p>10.1. Соглашение действует с момента его принятия Покупателем до момента получения им товара.<br />&nbsp;10.2. Интернет-магазин имеет право прекратить оказание всех Услуг при нарушении Покупателем данного Соглашения.<br />&nbsp;10.3. Если Покупатель предоставляет о себе неверную информацию или у Интернет-магазин есть серьезные основания полагать, что предоставленная Покупателем информация неверна, неполна или неточна, Интернет-магазин имеет право приостановить либо отменить заказ Покупателя и отказать ему в использовании своих Услуг.<br />&nbsp;10.4. Интернет-магазин имеет право прекратить оказание Услуг при нанесении Покупателем ущерба Интернет-магазину или третьим лицам путем непрямого нарушения условий настоящего Соглашения.<br />&nbsp;10.5. При прекращении Услуг Интернет-магазин не несет ответственности за извещение или неизвещение любых третьих сторон о лишении Покупателя доступа и за возможные последствия, возникшие в результате такого предупреждения или его отсутствия.</p>\r\n<p>11. Урегулирование споров</p>\r\n<p>11.1. Претензии Покупателя принимаются в письменном виде(или в виде электронного письма) в срок не позднее 3 (трех) рабочих дней с момента возникновения инцидента. Претензии рассматриваются в срок не более 10 (десяти) рабочих дней.<br />&nbsp;11.2. В случае возникновения любых споров или разногласий, связанных с исполнением Соглашения, Стороны приложат все усилия для их разрешения путем проведения переговоров между Сторонами. Если споры не будут разрешены путем переговоров, споры подлежат разрешению в порядке, установленном законодательством государства Российской Федерации. В случае возникновения неурегулированных претензий между сторонами, каждая из них может защищать свои нарушенные права в порядке, установленном Законодательством Российской Федерации.<br />&nbsp;11.3. В случае если какой-либо пункт данного Соглашения окажется не подлежащим буквальному исполнению, он толкуется в соответствии с действующим Законодательством с учетом первоначальных интересов Сторон, при этом оставшаяся часть Соглашения продолжает действовать в полной мере. Сложившая практика поведения сторон, либо практика оказания аналогичных услуг не могут быть причиной изменения положений настоящего Соглашения.<br />&nbsp;11.4. По всем остальным вопросам, не предусмотренным в настоящем Соглашении, Стороны руководствуются действующим законодательством Российской Федерации.</p>\r\n</div>', '2021-06-04 06:06:01', 'Пользовательское соглашение', 'пользовательское,соглашение', 'Пользовательское соглашение на нашем сайте'),
(12, 'Соглашение на обработку персональных данных', '<p><strong>Соглашение на обработку персональных данных</strong></p>\r\n<p>Настоящим в соответствии с Федеральным законом № 152-ФЗ &laquo;О персональных данных&raquo; от 27.07.2006 года Вы подтверждаете свое согласие на обработку&nbsp;интернет-магазином \"ТексЭт\" персональных данных: сбор, систематизацию, накопление, хранение, уточнение (обновление, изменение), использование, передачу исключительно в целях сбора и передачи Вам товара на Ваше имя.&nbsp; Интернет-магазин \"ТексЭт\", гарантирует конфиденциальность получаемой нами информации. Обработка персональных данных осуществляется в целях эффективного исполнения заказов, договоров и иных обязательств, принятых&nbsp;интернет-магазином \"ТексЭт\" в качестве обязательных к исполнению перед Вами.</p>\r\n<p>Настоящим особо оговаривается, что Вы даёте согласие на передачу Ваших персональных данных транспортной компании, Почте России или иной организации, с помощью которой&nbsp;<span>интернет-магазин \"ТексЭт\"</span> отправляет Вам заказ.</p>\r\n<p>Настоящее согласие распространяется на следующие Ваши персональные данные: фамилия, имя и отчество, серия и номер паспорта, адрес электронной почты, адрес прописки, почтовый адрес доставки заказов, контактный телефон, платёжные реквизиты.</p>\r\n<p>Срок действия Вашего согласия является неограниченным, однако, Вы вправе в любой момент отозвать настоящее согласие, путём направления письменного уведомления на адрес: <span>153521</span>,&nbsp;Россия,&nbsp;Ивановская область, <span>Ивановская.обл. Ново-Талицы ул. Автодоровская стр. 5</span>, &nbsp;для интернет-магазина \"ТексЭт\", с пометкой &laquo;отзыв согласия на обработку персональных данных&raquo;.</p>', '2021-10-21 01:10:56', 'Соглашение на обработку персональных данных', 'соглашение,на обработку,персональных,данных', 'Текст соглашение на обработку персональных данных на нашем сайте'),
(8, 'Статус заказа', '', '2020-09-22 00:09:00', '', '', ''),
(9, 'Оплата и доставка', '<h2>Как сделать <span class=\"rose\">заказ:</span></h2>\r\n  Для того, чтобы оформить заказ, Вам, необходимо: выбрать товар из каталога, в карточке товара проставить нужное количество на каждый размер и добавить в корзину покупок, после чего перейти на страницу оформления заказа (в корзину) и указать все необходимые данные.<br />Для физ. лиц: ФИО, серию № паспорта (для идентификации клиента при получении товара на почте или в транспортной компании), Email, контактный телефон, выбрать способ доставки (самовывоз, транспортной компанией до терминала или до двери), способ оплаты и адрес доставки. <br />Для юр. лиц и ИП: наименование организации, ИНН/КПП, ОГРН, юр. адрес, Email, телефон, ФИО контактного лица, выбрать способ доставки (самовывоз, транспортной компанией до терминала или до двери), способ оплаты и адрес доставки.</p>\r\n\r\n<p>После того, как Вы заполнили всю необходимую информацию, нажмите&nbsp;\"Отправить\" после этого мы с Вами свяжемся для подтверждения параметров заказа, уточнения наличия товара на складе, после согласования заказа выставим счёт для оплаты.</p>\r\n<p>Если вдруг Вам что то будет не понятно или не удобно при оформлении заказа на сайте или у вас возникнут дополнительные вопросы, Вы, можете направить заказ в свободной форме, с указанием необходимых моделей и размеров, на адрес электронной почты: Info@texet.biz</p>\r\n<ul>\r\n<li>Либо позвонить нам по телефону, заказать обратный звонок или написать прямо из карточки товара - \"Задать вопрос по товару\".</li>\r\n<li>На оплату счёта даётся 3 банковских дня, если в этот срок оплата не поступает по каким либо причинам, то заказанный товар снимается с резерва.</li>\r\n</ul>\r\n<p>Отгрузка производится после 100% предоплаты.</p>\r\n<p>Заказ можно оформить, как полными, так и не полными размерными рядами.</p>\r\n<p>После оплаты счёта, мы формируем заказ течение 5 дней уведомляем Вас о готовности и Вы можете приехать забрать свой заказ или мы отправляем его до терминала транспортной компании. <br />Вместе с грузом мы передаем или отправляем Вам оригиналы документов: Счет на оплату, Ваши экземпляры товарной накладной, договор и наши экземпляры для подписания Вами, которые, после подписания, просим выслать нам обратно.</p>\r\n<p>В случае отсутствия, заинтересовавшего, Вас, товара на складе, мы можем отшить его по предварительному заказу со скидкой до 15%. Так же возможен пошив изделий по Вашим образцам. Все детали по предварительному заказу оговариваются индивидуально.</p>\r\n<p>Обращаем Ваше внимание на то, что расцветки постоянно меняются и могут не совпадать с представленными на сайте. <br />Товар на реализацию не отпускается, возврат не реализованного товара надлежащего качества не возможен.</p>\r\n<h2><strong>Документы необходимые для заключения <span class=\"rose\">договора оптовой поставки:</span></strong></h2>\r\n<p><span style=\"text-decoration: underline;\">Если Вы &ndash; Юридическое лицо:</span><br /><br /><a name=\"skidki\"></a>1. Копия свидетельство о постановке на налоговый учет юридического лица (ИНН);<br />2. Копия свидетельства о государственной регистрации юр. лица (ОГРН);<br />3. Карточка предприятия. <br /><br /><span style=\"text-decoration: underline;\">Если Вы &ndash; Индивидуальный предприниматель:<br /></span><br />1. Копия свидетельства о постановке на налоговый учет индивидуального предпринимателя (ИНН);<br />2. Копия свидетельства о государственной регистрации ИП (ОГРНИП);</p>\r\n<h2><a name=\"skidki\"></a>Ценовая <span class=\"rose\">политика:</span></h2>Минимальная сумма мелкооптового заказа 4000 руб.<br />Розничные заказы отправляем 1-н раз в неделю, после 100% предоплаты.\r\n<p><span style=\"text-decoration: underline;\">Скидки на сумму заказа:</span></p>\r\n<ul>\r\n<li>от 15000 руб. скидка составит 10%.</li>\r\n<li>от 30000 руб. скидка составит 15%.</li>\r\n</ul>\r\n<p>При регистрации в личном кабинете у Вас появится возможность пользоваться накопительными скидками. Скидка в текущем месяце предоставляется в зависимости от суммы всех покупок в прошлом месяце.</p>\r\n<ul>\r\n<li>от 8000 руб. - скидка 3%</li>\r\n<li>от 16000 руб. - скидка 5%</li>\r\n<li>от 32000 руб. - скидка 8%</li>\r\n<li>от 64000 руб. - скидка 11%</li>\r\n</ul>\r\n<h2>Как <span class=\"rose\">оплатить:</span></h2>\r\n  Оплатить заказ можно любым удобным для Вас способом:\r\n  </p>\r\n\r\n<p>1. Оплата на наш расчетный счет.<br />\r\n2. Оплата на банковскую карту Сбербанка или ВТБ.<br />3. Оплата наличными при получении товара на нашем складе.</p>\r\n<h2>Условия <span class=\"rose\">доставки:</span></h2>\r\n<ul>\r\n<li>Товар можно забрать самостоятельно со склада предприятия.</li>\r\n<li>В случае, если Вы, далеко от нас, то после оплаты и сборки заказа, мы доставляем его до транспортной компании в г. Иваново - бесплатно.</li>\r\n<li>Доставка транспортными компаниями осуществляется за счет клиента.</li>\r\n</ul>\r\n<h2>ТК представленные в <span class=\"rose\">г. Иваново:</span></h2>\r\n<ul>\r\n<li>ЖелДор Экспедиция</li>\r\n<li>Деловые линии</li>\r\n<li>ПЭК</li>\r\n<li>СДЭК</li>\r\n<li>КИТ</li>\r\n<li>Байкал</li>\r\n<li>Энергия</li>\r\n<li>Трансвектор</li>\r\n</ul>\r\n<p>Возможность доставки другими компаниями необходимо уточнять. Стоимость доставки уточняйте на сайтах транспортных компаний.</p>', '2021-10-28 05:10:19', 'Оплата', 'Оплата', 'Оплата'),
(11, 'Использование файлов cookie', '<p>Закон Евросоюза о файлах&nbsp;cookies&nbsp;был принят в 2011 году, а в силу вступил 26 мая 2012. Он обязывает сайты, использующие&nbsp;cookie&nbsp;файлы, уведомлять об этом своих посетителей. Помимо обычного уведомления, сайты должны предоставить список конкретных&nbsp;cookie, а также их предназначение.</p>\r\n<p>Для лучшего понимания ситуации и самого закона, стоит разобраться с понятием&nbsp;cookie.</p>\r\n<h2>ЧТО ТАКОЕ&nbsp;COOKIE-ФАЙЛ?</h2>\r\n<p>Файл&nbsp;cookie&nbsp;или просто&nbsp;куки&nbsp;&ndash; небольшой фрагмент данных, передаваемый сайтом на компьютер пользователя и хранящийся там же. Предназначены&nbsp;куки&nbsp;для:</p>\r\n<ul>\r\n<li>Настройки параметров сайта. Язык сайта, время и прочие;</li>\r\n<li>Оптимизации расходов трафика;</li>\r\n<li>Отслеживания предпочтений пользователя;</li>\r\n<li>Выдачи релевантных объявлений для пользователя, на основе информации собранной благодаря&nbsp;cookie</li>\r\n</ul>\r\n<p>Основная задача&nbsp;cookie&nbsp;&ndash; сбор предпочтений пользователя сети.</p>\r\n<p>Все файлы&nbsp;куки&nbsp;делятся на два типа: сеансовые и постоянные&nbsp;cookie.</p>\r\n<p>Сеансовые&nbsp;cookie&nbsp;файлы используются для присвоения уникального номера компьютеру пользователя и поддержания работоспособности сайта. Такой тип&nbsp;куки&nbsp;файлов удаляется сразу после закрытия&nbsp;браузера.</p>\r\n<p>Постоянные&nbsp;cookie&nbsp;файлы находятся на компьютере определенное время или до удаления их самым пользователем. Такой тип файлов помогает&nbsp;веб-мастерам собирать подробную информацию о предпочтениях пользователей и предоставлять им интересующую информацию.</p>\r\n<p>Одной из особенностей этих типов&nbsp;куки, является необходимость запроса на соглашение. В случае с сеансовыми файлами&nbsp;cookie, запрос на разрешение использования не высылается, так как с помощью таких файлов функционирует сайт и без них работа ресурса невозможна. Использования постоянных&nbsp;куки&nbsp;файлов всегда подразумевает запрос на согласие.</p>\r\n<h2>НАСТРОЙКИ&nbsp;КУКИ</h2>\r\n<p>Пользователи могут сами регулировать и настраивать&nbsp;куки&nbsp;файлы. Существует несколько способов настройки файлов&nbsp;cookie:</p>\r\n<ul>\r\n<li>Разрешить использование всех&nbsp;cookie&nbsp;файлов. Такой вариант подразумевает разрешение на использование любых&nbsp;куки&nbsp;файлов, интегрированных на посещаемом сайте;</li>\r\n<li>Блокировать любые&nbsp;cookie&nbsp;файлы. При таком варианте настройки пользоваться ресурсом станет затруднительно, многие функции прекратят свою работу, так как требуют использование&nbsp;кукифайлов;</li>\r\n<li>Вручную принимать либо отклонять&nbsp;cookie&nbsp;файлы. Самый просто вариант не требующий дополнительных манипуляций.</li>\r\n</ul>\r\n<p>Настройки&nbsp;куки&nbsp;происходят в меню настроек&nbsp;браузера. Стоит отметить что все пункты не являются необратимыми и могут быть перенастроены в любое время. Также сам процесс настраивания может незначительно отличатся в зависимости от&nbsp;браузера, который используется. &nbsp;&nbsp;</p>\r\n<h2>УДАЛЕНИЕ ФАЙЛОВ&nbsp;COOKIE</h2>\r\n<p>Пользователь может самостоятельно очистить&nbsp;кэш&nbsp;от файлов&nbsp;cookie. Для этого стоит выполнить простую инструкцию, которая может незначительно отличатся в зависимости от интерфейса используемого&nbsp;браузера:</p>\r\n<ol>\r\n<li>Зайти в панель настройки&nbsp;веб-браузера;</li>\r\n<li>Найти пункт история;</li>\r\n<li>Выбрать пункт очистить&nbsp;куки;</li>\r\n<li>Установить период в пределах которого все&nbsp;куки&nbsp;файлы будут удалены (день, неделя, месяц и тд.)</li>\r\n</ol>\r\n<p>После процедуры сохраненные пароли на сайтах, где пользователь проходил авторизацию, исчезнут.</p>\r\n<h2>ЗАКЛЮЧЕНИЕ</h2>\r\n<p>Файлы&nbsp;куки&nbsp;&ndash; стандартный инструмент любого&nbsp;веб-сайта, которые необходим для его функционирования. Создан подобный тип файлов для помощи&nbsp;вебмастерам&nbsp;подбирать информацию, напрямую интересующую целевую аудиторию их ресурсов.</p>', '2021-06-04 06:06:32', 'Использование файлов cookie', 'Использование,файлов,cookie', 'Информация по использованию файлов cookie на нашем сайте'),
(13, 'Вакансии', '<div class=\"vak\">\r\n<div class=\"v1\">&nbsp;</div>\r\n<div class=\"v2\">\r\n<p><span style=\"text-decoration: underline;\">ООО ТексЭт осуществляет набор сотрудников по следующим специальностям:</span></p>\r\n<p><strong>Швея<br /></strong>Пошив льняного ассортимента, представленного на сайте.<br />Требования: Профессионализм, ответственный подход к работе, пунктуальность, исполнительность. <br /><br />Опыт в портном деле приветствуется.</p>\r\n<ul>\r\n<li>З/П 100 т.р.</li>\r\n<li>Надбавки за выработку, стаж.</li>\r\n<li>Официальное трудоустройство.</li>\r\n<li>Оплата проезда.</li>\r\n<li>Стабильная работа в стабильном предприятии.</li>\r\n<li>Производство собственных линеек одежды.</li>\r\n</ul>\r\n<p><br /><strong>Ученики швей</strong><br />Обсуждается отдельно.</p>\r\n<p><strong>Раскройщик</strong><br />Требования: Профессионализм, ответственный подход к работе, пунктуальность, исполнительность, знание раскройного дела. Знание закройного дела приветствуется.<br />Возможно на подработку, не полный рабочий день.<br /><br /><strong>Работник на петли, пуговицы, на влажно тепловую обработку (ВТО) (утюжка), упаковку</strong><br />Возможно на подработку, не полный&nbsp;рабочий&nbsp;день.</p>\r\n<p><span style=\"text-decoration: underline;\"><strong>Телефон для связи: +7 (4932) 20-49-83</strong></span></p>\r\n</div>\r\n</div>', '2023-08-10 08:08:59', 'Вакансии', 'Вакансии', 'Вакансии');

